window.ToyData.register("k12-math_5a_rjb.json","{\"book\":[5,\"上\",\"五上\",\"五年级上册\"],\"topics\":[[\"cnm_p132\",\"math_5a_rjb_cpt1\",\"小数乘整数\",\"概念\",\"用一个小数与一个整数相乘，先按整数乘法计算，再根据因数中的小数位数确定积中的小数点位置。\",[[\"1\",\"小数乘法\",\"\"]],{\"examples\":[\"9.5×3=28.5\"]}],[\"cnm_p133\",\"math_5a_rjb_cpt2\",\"小数乘小数\",\"概念\",\"小数与小数相乘时，先按整数相乘，再根据两个因数中小数位数之和确定积中的小数点位置。\",[[\"1\",\"小数乘法\",\"\"]],{\"examples\":[\"2.4×0.8=1.92\"]}],[\"cnm_k5acpt3\",\"math_5a_rjb_cpt3\",\"小数点位置确定规则\",\"概念\",\"在小数乘法中，积的小数位数等于两个因数小数位数之和。\",[[\"1\",\"小数乘法\",\"\"]],{}],[\"cnm_k5acpt4\",\"math_5a_rjb_cpt4\",\"小数乘法中的数量关系\",\"概念\",\"一个数（0除外）乘大于1的数，积比原数大；乘小于1的数，积比原数小。\",[[\"1\",\"小数乘法\",\"\"]],{}],[\"cnm_k5acpt5\",\"math_5a_rjb_cpt5\",\"乘法运算律在小数中的适用\",\"概念\",\"小数乘法同样满足交换律、结合律和分配律，可用于简便计算。\",[[\"1\",\"小数乘法\",\"\"]],{\"examples\":[\"0.65×202 = 0.65×200 + 0.65×2\"]}],[\"cnm_k5askl1\",\"math_5a_rjb_skl1\",\"列竖式计算小数乘法\",\"技能\",\"将小数乘法转换为整数竖式计算，再根据小数位数确定小数点位置。\",[[\"1\",\"小数乘法\",\"\"]],{}],[\"cnm_k5askl2\",\"math_5a_rjb_skl2\",\"小数乘法估算\",\"技能\",\"将小数按实际情境取近似值，进行快速判断或估算。\",[[\"1\",\"小数乘法\",\"\"]],{}],[\"cnm_k5askl3\",\"math_5a_rjb_skl3\",\"根据运算律进行简便计算\",\"技能\",\"利用交换律、结合律、分配律对小数乘法进行化简，提高计算效率。\",[[\"1\",\"小数乘法\",\"\"]],{}],[\"cnm_k5acpt6\",\"math_5a_rjb_cpt6\",\"数对\",\"概念\",\"用一对按照先后顺序排列的数来表示位置，通常第一个数表示列（或横向距离），第二个数表示行（或纵向距离）。\",[[\"2\",\"位置\",\"\"]],{\"examples\":[\"张亮的位置用数对（2,3）表示。教材原文第1页\"]}],[\"cnm_k5acpt7\",\"math_5a_rjb_cpt7\",\"在方格图上确定位置\",\"概念\",\"通过横向和纵向的格子数量来确定某个点或物体在方格图上的准确位置。\",[[\"2\",\"位置\",\"\"]],{\"examples\":[\"动物园示意图、识字表中的点位标注\"]}],[\"cnm_k5acpt8\",\"math_5a_rjb_cpt8\",\"位置的描述\",\"概念\",\"根据方向和距离描述物体的位置，例如‘以东400米，再往北300米’。\",[[\"2\",\"位置\",\"\"]],{\"examples\":[\"图书馆的位置：以东400m，再往北300m\"]}],[\"cnm_k5acpt9\",\"math_5a_rjb_cpt9\",\"平移与位置变化\",\"概念\",\"图形中的点按相同方向和距离移动，所有点的数对同时进行相应变化。\",[[\"2\",\"位置\",\"\"]],{\"examples\":[\"三角形各顶点平移5个单位\"]}],[\"cnm_k5askl4\",\"math_5a_rjb_skl4\",\"用数对表示位置的方法\",\"技能\",\"根据给定的图或坐标体系，依次确定横向位置（列）与纵向位置（行），并写成（x, y）形式。\",[[\"2\",\"位置\",\"\"]],{}],[\"cnm_k5askl5\",\"math_5a_rjb_skl5\",\"根据数对在图上定位点\",\"技能\",\"根据给定的数对，在方格图中找到对应的横向与纵向位置并标出。\",[[\"2\",\"位置\",\"\"]],{}],[\"cnm_p137\",\"math_5a_rjb_cpt10\",\"除数是整数的小数除法\",\"概念\",\"在除数为整数的情况下，用竖式按整数除法的方法进行小数除法计算，按照商中小数点与被除数对齐的规则进行。\",[[\"3\",\"小数除法\",\"\"]],{}],[\"cnm_k5acpt11\",\"math_5a_rjb_cpt11\",\"除数是小数的小数除法\",\"概念\",\"通过同时将除数和被除数乘以相同的10、100等，使除数化为整数，再按除数是整数的小数除法进行计算。\",[[\"3\",\"小数除法\",\"\"]],{}],[\"cnm_k5acpt12\",\"math_5a_rjb_cpt12\",\"小数点移动规则\",\"概念\",\"当将除数变为整数时，除数的小数点向右移动几位，被除数的小数点也向右移动相同的位数。\",[[\"3\",\"小数除法\",\"\"]],{}],[\"cnm_k5acpt13\",\"math_5a_rjb_cpt13\",\"有限小数\",\"概念\",\"小数部分的位数有限的十进制小数。\",[[\"3\",\"小数除法\",\"\"]],{}],[\"cnm_k5acpt14\",\"math_5a_rjb_cpt14\",\"循环小数\",\"概念\",\"小数部分从某一位起，数字按一定节奏无限重复出现的小数。\",[[\"3\",\"小数除法\",\"\"]],{\"examples\":[\"5.333…\",\"7.14545…\"]}],[\"cnm_k5acpt15\",\"math_5a_rjb_cpt15\",\"商的近似数\",\"概念\",\"对除法的结果根据需要按“四舍五入”规则保留指定位数的小数。\",[[\"3\",\"小数除法\",\"\"]],{}],[\"cnm_k5askl6\",\"math_5a_rjb_skl6\",\"小数除法竖式计算方法\",\"技能\",\"根据除数是否为整数选择不同策略，并按位计算商，必要时在被除数后补0。\",[[\"3\",\"小数除法\",\"\"]],{}],[\"cnm_k5askl7\",\"math_5a_rjb_skl7\",\"四舍五入取近似数\",\"技能\",\"将结果计算到需要保留的小数位后一位，再按“四舍五入”规则确定最终位数。\",[[\"3\",\"小数除法\",\"\"]],{}],[\"cnm_p140\",\"math_5a_rjb_cpt16\",\"可能性\",\"概念\",\"在一个随机事件中，不同结果发生的机会大小。\",[[\"4\",\"可能性\",\"\"]],{\"examples\":[\"从盒子里随机摸球，摸出不同颜色球的可能性大小不同。\"]}],[\"cnm_k5acpt17\",\"math_5a_rjb_cpt17\",\"一定事件\",\"概念\",\"在给定情境中必然发生的事件。\",[[\"4\",\"可能性\",\"\"]],{\"examples\":[\"盒子里全是黄球，摸出的一定是黄球。\"]}],[\"cnm_k5acpt18\",\"math_5a_rjb_cpt18\",\"不可能事件\",\"概念\",\"在一定条件下必然不会发生的事件。\",[[\"4\",\"可能性\",\"\"],[\"25\",\"第二十五章 概率初步\",\"第一节 随机事件与概率\"],[\"10\",\"第十章 概率\",\"第一节 随机事件与概率\"]],{\"examples\":[\"盒子里没有蓝球，摸出蓝球是不可能的。\",\"抽到的数字是0\",\"骰子点数为7\"]}],[\"cnm_k5acpt19\",\"math_5a_rjb_cpt19\",\"可能事件\",\"概念\",\"在给定情境中可能发生也可能不发生的事件。\",[[\"4\",\"可能性\",\"\"]],{\"examples\":[\"盒子里有红球也有黄球，摸出任一种颜色都属于可能事件。\"]}],[\"cnm_k5acpt20\",\"math_5a_rjb_cpt20\",\"可能性大小比较\",\"概念\",\"通过数量、面积等方式比较不同结果的发生机会大小。\",[[\"4\",\"可能性\",\"\"]],{\"examples\":[\"转盘某颜色区域越大，停在该颜色的可能性越大。\"]}],[\"cnm_k5askl8\",\"math_5a_rjb_skl8\",\"通过实验估计可能性\",\"技能\",\"通过多次重复试验记录结果，根据频率估计不同结果的可能性。\",[[\"4\",\"可能性\",\"\"]],{}],[\"cnm_k5acpt21\",\"math_5a_rjb_cpt21\",\"用字母表示数\",\"概念\",\"用字母表示任意数值或数量关系，如a+30表示爸爸年龄。\",[[\"5\",\"简易方程\",\"\"]],{\"examples\":[\"a+30\",\"6x\"]}],[\"cnm_k5acpt22\",\"math_5a_rjb_cpt22\",\"运算律的字母表示\",\"概念\",\"用字母简明表示加法、乘法的交换律、结合律和分配律。\",[[\"5\",\"简易方程\",\"\"]],{\"examples\":[\"a+b=b+a\",\"a(b+c)=ab+ac\"]}],[\"cnm_k5acpt23\",\"math_5a_rjb_cpt23\",\"等式的性质\",\"概念\",\"等式两边同时加、减、乘、除同一个数（除0外）仍保持相等。\",[[\"5\",\"简易方程\",\"\"]],{\"examples\":[\"a=b → a+3=b+3\"]}],[\"cnm_k5acpt24\",\"math_5a_rjb_cpt24\",\"方程\",\"概念\",\"含有未知数的等式，由已知数与用字母表示的未知数组成，表达数量之间的相等关系。\",[[\"5\",\"简易方程\",\"\"],[\"6\",\"整理和复习\",\"\"],[\"3\",\"第三章 一元一次方程\",\"第一节 从算式到方程\"]],{\"examples\":[\"100+x=250\",\"3x=18\"],\"aliases\":[\"equation\"]}],[\"cnm_k5acpt25\",\"math_5a_rjb_cpt25\",\"解方程\",\"概念\",\"利用等式性质求使方程成立的未知数的值。\",[[\"5\",\"简易方程\",\"\"]],{\"examples\":[\"3x=18 → x=6\"]}],[\"cnm_k5acpt26\",\"math_5a_rjb_cpt26\",\"用方程解决实际问题\",\"概念\",\"根据问题中的数量关系列出方程并求解。\",[[\"5\",\"简易方程\",\"\"]],{}],[\"cnm_k5askl9\",\"math_5a_rjb_skl9\",\"将数量关系转化为代数表达\",\"技能\",\"把实际情境中的数量关系抽象成含字母的式子或方程。\",[[\"5\",\"简易方程\",\"\"]],{}],[\"cnm_k5askl10\",\"math_5a_rjb_skl10\",\"依据等式性质进行变形\",\"技能\",\"运用等式的性质进行移项、化简，求出未知数。\",[[\"5\",\"简易方程\",\"\"]],{}],[\"cnm_p147\",\"math_5a_rjb_cpt27\",\"平行四边形的面积\",\"概念\",\"平行四边形的面积等于它的底乘以高。\",[[\"6\",\"多边形的面积\",\"\"]],{\"formula\":\"S = a × h\"}],[\"cnm_p148\",\"math_5a_rjb_cpt28\",\"三角形的面积\",\"概念\",\"三角形的面积等于底乘以高再除以2。\",[[\"6\",\"多边形的面积\",\"\"]],{\"formula\":\"S = a × h ÷ 2\"}],[\"cnm_p149\",\"math_5a_rjb_cpt29\",\"梯形的面积\",\"概念\",\"梯形的面积等于上底与下底的和乘以高再除以2。\",[[\"6\",\"多边形的面积\",\"\"]],{\"formula\":\"S = (a + b) × h ÷ 2\"}],[\"cnm_k5acpt30\",\"math_5a_rjb_cpt30\",\"面积转化方法\",\"概念\",\"通过分割、平移、拼合等方式将复杂图形转化为已知面积公式的简单图形，面积保持不变。\",[[\"6\",\"多边形的面积\",\"\"]],{}],[\"cnm_k5acpt31\",\"math_5a_rjb_cpt31\",\"数方格估计面积\",\"概念\",\"利用方格纸，通过数满格和半格近似估计不规则图形面积的方法。\",[[\"6\",\"多边形的面积\",\"\"]],{}],[\"cnm_k5askl11\",\"math_5a_rjb_skl11\",\"图形转化求面积\",\"技能\",\"将复杂或不规则图形转化为长方形、平行四边形、三角形等基本图形，以便计算面积。\",[[\"6\",\"多边形的面积\",\"\"]],{}],[\"cnm_k5askl12\",\"math_5a_rjb_skl12\",\"利用底和高计算面积\",\"技能\",\"根据图形的底与高，套用相应面积公式进行计算。\",[[\"6\",\"多边形的面积\",\"\"]],{}],[\"cnm_k5askl13\",\"math_5a_rjb_skl13\",\"利用方格估计面积\",\"技能\",\"通过数方格的方法估计规则或不规则图形的面积。\",[[\"6\",\"多边形的面积\",\"\"]],{}],[\"cnm_p151\",\"math_5a_rjb_cpt32\",\"植树问题\",\"概念\",\"在一定长度的道路或周长上按固定间隔设置物体（如树、灯、旗等），根据是否在两端放置来确定数量的数学问题。\",[[\"7\",\"数学广角——植树问题\",\"\"]],{\"examples\":[\"在100米长的路一侧每隔5米栽一棵树，两端都要栽。\"]}],[\"cnm_k5acpt33\",\"math_5a_rjb_cpt33\",\"间隔数与棵树数的关系\",\"概念\",\"在线段上若两端都放物体，则物体数量 = 间隔数 + 1；若两端都不放，则物体数量 = 间隔数 - 1；若只放一端，则物体数量 = 间隔数。\",[[\"7\",\"数学广角——植树问题\",\"\"]],{\"examples\":[\"20个间隔，两端都栽，共21棵树。\"]}],[\"cnm_k5acpt34\",\"math_5a_rjb_cpt34\",\"闭合图形的均匀布点\",\"概念\",\"在圆周等封闭曲线周围按固定间隔放置物体时，由于不存在“端点”，物体数量等于间隔数量。\",[[\"7\",\"数学广角——植树问题\",\"\"]],{\"examples\":[\"圆形池塘周长120米，每隔10米栽树，共12棵。\"]}],[\"cnm_k5askl14\",\"math_5a_rjb_skl14\",\"画线段图或示意图检验数量关系\",\"技能\",\"通过画线段图、点与间隔的关系图来验证计算是否正确，直观理解间隔数与点数的对应关系。\",[[\"7\",\"数学广角——植树问题\",\"\"]],{}],[\"cnm_k5acpt35\",\"math_5a_rjb_cpt35\",\"小数的乘除法\",\"概念\",\"将小数的乘除法转化为整数的乘除法进行计算。\",[[\"8\",\"总复习\",\"\"]],{\"examples\":[\"2.7×3，2.4÷6\"]}],[\"cnm_k5acpt36\",\"math_5a_rjb_cpt36\",\"用字母表示式子\",\"概念\",\"用含有字母的式子表示运算律、计算公式和数量关系。\",[[\"8\",\"总复习\",\"\"]],{\"examples\":[\"a(b+c)=ab+ac\",\"s=vt\"]}],[\"cnm_k5acpt37\",\"math_5a_rjb_cpt37\",\"面积计算公式\",\"概念\",\"将平行四边形、三角形和梯形转化为学过的图形推导面积公式。\",[[\"8\",\"总复习\",\"\"]],{}],[\"cnm_k5acpt38\",\"math_5a_rjb_cpt38\",\"方程及其解法\",\"概念\",\"用字母表示未知数，根据等量关系列方程并求解。\",[[\"8\",\"总复习\",\"\"]],{\"examples\":[\"2x+7=13\"]}],[\"cnm_k5acpt39\",\"math_5a_rjb_cpt39\",\"数对与确定位置\",\"概念\",\"用两个数的有序数对表示平面上的位置。\",[[\"8\",\"总复习\",\"\"]],{}],[\"cnm_k5acpt40\",\"math_5a_rjb_cpt40\",\"可能性问题\",\"概念\",\"比较事件发生的可能性大小。\",[[\"8\",\"总复习\",\"\"]],{\"examples\":[\"指针落在不同颜色区域的可能性\"]}],[\"cnm_k5acpt41\",\"math_5a_rjb_cpt41\",\"直角三角形与平方关系\",\"概念\",\"直角三角形三边为a、b、c（c为斜边）时，三个对应正方形的面积满足a²+b²=c²的关系。\",[[\"8\",\"总复习\",\"\"]],{}],[\"cnm_k5askl15\",\"math_5a_rjb_skl15\",\"转化思想\",\"技能\",\"利用已经学过的知识解决新问题，将复杂问题转化为熟悉的问题来解决。\",[[\"8\",\"总复习\",\"\"]],{}],[\"cnm_k5askl16\",\"math_5a_rjb_skl16\",\"用字母符号表达数量关系\",\"技能\",\"用字母建立数量关系式，包括运算律、公式及实际问题关系式。\",[[\"8\",\"总复习\",\"\"]],{}],[\"cnm_k5askl17\",\"math_5a_rjb_skl17\",\"列方程解决问题\",\"技能\",\"根据题意设未知数，利用等量关系列方程求解实际问题。\",[[\"8\",\"总复习\",\"\"]],{}],[\"cnm_k5askl18\",\"math_5a_rjb_skl18\",\"图形变换与位置缩放\",\"技能\",\"将数对的坐标进行倍数变化，理解放大或缩小图形的效果。\",[[\"8\",\"总复习\",\"\"]],{}]],\"dependencies\":[[\"cnm_p132\",\"cnm_p133\",\"“两个因数都是小数怎么计算呢？可以把它们看作整数来计算吗？”（例3）\"],[\"cnm_k5acpt3\",\"cnm_k5askl1\",\"使用竖式计算必须会确定小数点位置。\"],[\"cnm_k5acpt4\",\"cnm_k5askl2\",\"利用积与因数的大小关系进行估算判断。\"],[\"cnm_k5acpt5\",\"cnm_k5askl3\",\"小数乘法的运算律使简便计算成为可能。\"],[\"cnm_k5acpt6\",\"cnm_k5acpt7\",\"张亮的位置可以用数对（2，3）表示 → 学生需用数对在图中定位。教材第1页\"],[\"cnm_k5acpt7\",\"cnm_k5acpt9\",\"要表示平移前后点的位置，需掌握方格图定位方法。第6题\"],[\"cnm_p137\",\"cnm_k5acpt11\",\"“可以把除数转化成整数，同时……然后按除数是整数的小数除法进行计算。”（除数是小数的小数除法部分）\"],[\"cnm_k5acpt14\",\"cnm_k5acpt15\",\"循环小数常需取近似数，如“先用循环小数表示所得的商，再保留两位小数写出近似数。”\"],[\"cnm_k5askl6\",\"cnm_k5acpt15\",\"取近似数前必须先得到精确商。\"],[\"cnm_p140\",\"cnm_k5askl8\",\"只有理解可能性，才能通过实验估计其大小，如“重复20次，记录结果”。\"],[\"cnm_k5acpt21\",\"cnm_k5acpt24\",\"“像100+x=250…含有未知数的等式是方程。” p.?\"],[\"cnm_k5acpt23\",\"cnm_k5acpt25\",\"“等式两边…仍然相等”用于解方程 p.?\"],[\"cnm_k5acpt25\",\"cnm_k5acpt26\",\"实际问题需要列方程并解方程 p.?\"],[\"cnm_k5acpt30\",\"cnm_p147\",\"观察原来的平行四边形和转化后的长方形，你发现了什么？\"],[\"cnm_k5acpt30\",\"cnm_p148\",\"观察拼成的平行四边形和原来的三角形，你发现了什么？\"],[\"cnm_k5acpt30\",\"cnm_p149\",\"观察拼成的平行四边形和原来的梯形，你发现了什么？\"],[\"cnm_k5acpt31\",\"cnm_k5askl13\",\"方格纸上满格的一共有18格，不是满格的也有18格。\"],[\"cnm_k5askl11\",\"cnm_p147\",\"平移剪下的三角形拼成长方形。\"],[\"cnm_k5askl12\",\"cnm_p147\",\"S = ah\"],[\"cnm_k5askl12\",\"cnm_p148\",\"S = ah ÷ 2\"],[\"cnm_k5askl12\",\"cnm_p149\",\"S = (a+b)h ÷ 2\"],[\"cnm_k5acpt33\",\"cnm_k5acpt34\",\"圆形池塘按间隔栽树没有端点，因此棵数=间隔数。（教材）\"],[\"cnm_k5askl14\",\"cnm_k5acpt33\",\"应该栽5棵，直接用除法计算不对，要画图检验。（教材20米示例）\"],[\"cnm_k5acpt35\",\"cnm_k5acpt38\",\"“利用已经学过的知识解决新问题”\"],[\"cnm_k5acpt39\",\"cnm_k5askl18\",\"数对用于确定位置，后文用于坐标缩放\"],[\"cnm_k5acpt24\",\"cnm_k7acpt41\",\"这样的方程叫做一元一次方程。\"]],\"relations\":[[\"cnm_p133\",\"cnm_k5acpt3\",\"relates_to\"],[\"cnm_k5acpt6\",\"cnm_k5acpt9\",\"relates_to\"],[\"cnm_k5acpt11\",\"cnm_k5acpt12\",\"relates_to\"],[\"cnm_k5acpt14\",\"cnm_k5acpt13\",\"is_a\"],[\"cnm_k5askl7\",\"cnm_k5acpt15\",\"is_a\"],[\"cnm_k5acpt17\",\"cnm_p140\",\"is_a\"],[\"cnm_k5acpt18\",\"cnm_p140\",\"is_a\"],[\"cnm_k5acpt19\",\"cnm_p140\",\"is_a\"],[\"cnm_p140\",\"cnm_k5acpt20\",\"relates_to\"],[\"cnm_k5acpt22\",\"cnm_k5acpt21\",\"relates_to\"],[\"cnm_k5acpt24\",\"cnm_k5acpt25\",\"relates_to\"],[\"cnm_k5askl10\",\"cnm_k5acpt23\",\"is_a\"],[\"cnm_p147\",\"cnm_p148\",\"relates_to\"],[\"cnm_p147\",\"cnm_p149\",\"relates_to\"],[\"cnm_k5acpt31\",\"cnm_k5acpt30\",\"relates_to\"],[\"cnm_k5acpt33\",\"cnm_p151\",\"is_a\"],[\"cnm_k5acpt36\",\"cnm_k5acpt38\",\"relates_to\"],[\"cnm_k5acpt37\",\"cnm_k5askl15\",\"relates_to\"],[\"cnm_k5acpt41\",\"cnm_k5acpt37\",\"relates_to\"],[\"cnm_k5acpt24\",\"cnm_k7acpt43\",\"relates_to\"],[\"cnm_k5acpt18\",\"cnm_k9acpt73\",\"is_a\"],[\"cnm_k5acpt18\",\"cnm_k9acpt71\",\"is_a\"]]}");
